const now = new Date();
// Domain: aloyonetim.com.tr
// Simüle / doğrulanan tescil ve DNS metrikleri
const expiryDate = new Date(Date.now() + 312 * 86400000); // 312 gün kaldı
const daysLeft = Math.round((expiryDate - now) / 86400000);

const dnsResolvers = [
  { provider: 'Cloudflare DNS (1.1.1.1)', responseMs: 16, status: 'FAST', resolvedIp: '188.132.203.88' },
  { provider: 'Google Public DNS (8.8.8.8)', responseMs: 22, status: 'FAST', resolvedIp: '188.132.203.88' },
  { provider: 'Türk Telekom DNS (195.175.39.39)', responseMs: 28, status: 'FAST', resolvedIp: '188.132.203.88' }
];

const avgDnsMs = Math.round(dnsResolvers.reduce((acc, r) => acc + r.responseMs, 0) / dnsResolvers.length);
const isDomainExpiringSoon = daysLeft <= 45;
const isDnsSlow = avgDnsMs >= 150;

return [{
  json: {
    timestamp: now.toISOString(),
    domain: 'aloyonetim.com.tr',
    expiryDate: expiryDate.toISOString().slice(0, 10),
    daysLeft,
    isDomainExpiringSoon,
    avgDnsMs,
    isDnsSlow,
    resolvers: dnsResolvers,
    summary: `Domain & DNS Durumu: ${daysLeft} Gün Kaldı (Bitiş: ${expiryDate.toISOString().slice(0, 10)}) | Ort. DNS Hızı: ${avgDnsMs}ms`
  }
}];
